                    titles[j] = resolveParametersInString(build, listener, titles[j]);
                }
            }

            List<String> reports = new ArrayList<>();
            for (int j=0; j < csvReports.size(); j++) {
                String report = csvReports.get(j);
                report = report.trim();
                // On windows file paths contains back slashes, but
