                    linkref = MarkupParser.cleanLink( linkref );
                    callMutatorChain( m_localLinkMutatorChain, linkref );
                    final String matchedLink = m_linkParsingOperations.linkIfExists( linkref );
                    if( matchedLink != null ) {
