        var contentType = mpu.blobMetadata().getContentMetadata().getContentType();
        if (contentType != null) {
            blobBuilder.contentType(contentType);
        }
        var expires = mpu.blobMetadata().getContentMetadata().getExpires();
        if (expires != null) {
            blobBuilder.expires(expires);
        }
