                Date unmodifiedSince = options.getIfUnmodifiedSince();
                if (lastModifiedTime.after(unmodifiedSince)) {
                    HttpResponse.Builder response = HttpResponse.builder().statusCode(Status.PRECONDITION_FAILED.getStatusCode());
