                    .contentDisposition(contentDisposition)
                    .contentEncoding(contentEncoding)
                    .contentLanguage(contentLanguage)
                    .contentLength(size)
                    .contentMD5(hashCode)
                    .contentType(contentType)
                    .eTag(eTag)
