            var actualHashCode = is.hash();
            var expectedHashCode = metadata.getContentMD5AsHashCode();
            if (expectedHashCode != null && !actualHashCode.equals(expectedHashCode)) {
                Files.delete(tmpPath);
                throw returnResponseException(400);
