                    builder.add(new StorageMetadataImpl(StorageType.BLOB,
                            /*id=*/ null, name,
                            /*location=*/ null, /*uri=*/ null,
                            eTag, creationTime, lastModifiedTime,
                            Map.of(), attr.size(), tier));
                }
            }
        } catch (NoSuchFileException nsfe) {
            // ignore
        }
    }

