                    if (next != null) {
                        marker = temp.last().getName();
                    }
                }
                sorted = temp;
            }
            return new PageSetImpl<StorageMetadata>(sorted, marker);
        } catch (IOException ioe) {
            logger.error("unexpected exception", ioe);
            throw new RuntimeException(ioe);
        }
    }

