        }
    }

    private static HttpResponseException returnResponseException(int code) {
        var response = HttpResponse.builder().statusCode(code).build();
        return new HttpResponseException(new HttpCommand(HttpRequest.builder()
                .method("GET")
                .endpoint("http://stub")
                .build()), response);
    }

